-- Testnet evidence window (2026-10-16, approved by Paul): the two time checks that pinned the live evidence window
-- at 5 s follow it per network. Mainnet: exactly the old bounds (5 s). Testnet: 10 s, the cap of
-- COPY_LIVE_TESTNET_EVIDENCE_MAX_AGE_MS (LIVE_TESTNET_EVIDENCE_MAX_AGE_CAP_MS = 2 x LIVE_EVIDENCE_MAX_AGE_MS = 10000 ms;
-- the app enforces the window in force, these checks only its ceiling). A row of any other network fails the check
-- (and the identity checks). Each check stays at or above the app's window on the row's network (mainnet = it, 5 s;
-- testnet = its ceiling, 10 s); the network is the row's own `network` column, which both tables have (NOT NULL).
-- A no-op for Stage: it holds only mainnet rows, whose bounds are exactly the old ones, and every existing row was
-- written under the 5 s bounds, so the plain drop-and-add (in the migration's transaction) validates unchanged.
-- Rollback: the previous checks (0046, 0048) are stricter; restoring them fails only on testnet rows written with a
-- window above 5 s (delete or keep those before restoring).
ALTER TABLE "copy_follower_observations" DROP CONSTRAINT "copy_follower_observations_time_check";--> statement-breakpoint
ALTER TABLE "copy_live_position_baselines" DROP CONSTRAINT "copy_live_baseline_time_check";--> statement-breakpoint
ALTER TABLE "copy_follower_observations" ADD CONSTRAINT "copy_follower_observations_time_check" CHECK ("copy_follower_observations"."completed_at" >= "copy_follower_observations"."observed_at" and "copy_follower_observations"."earliest_provider_time" <= "copy_follower_observations"."completed_at" and (("copy_follower_observations"."network" = 'mainnet' and "copy_follower_observations"."completed_at" <= "copy_follower_observations"."observed_at" + interval '5 seconds' and "copy_follower_observations"."earliest_provider_time" >= "copy_follower_observations"."completed_at" - interval '5 seconds') or ("copy_follower_observations"."network" = 'testnet' and "copy_follower_observations"."completed_at" <= "copy_follower_observations"."observed_at" + interval '10 seconds' and "copy_follower_observations"."earliest_provider_time" >= "copy_follower_observations"."completed_at" - interval '10 seconds')));--> statement-breakpoint
ALTER TABLE "copy_live_position_baselines" ADD CONSTRAINT "copy_live_baseline_time_check" CHECK (extract(epoch from "copy_live_position_baselines"."observed_at") > 0 and "copy_live_position_baselines"."completed_at" >= "copy_live_position_baselines"."observed_at" and "copy_live_position_baselines"."created_at" >= "copy_live_position_baselines"."completed_at" and (("copy_live_position_baselines"."network" = 'mainnet' and "copy_live_position_baselines"."created_at" <= "copy_live_position_baselines"."observed_at" + interval '5 seconds') or ("copy_live_position_baselines"."network" = 'testnet' and "copy_live_position_baselines"."created_at" <= "copy_live_position_baselines"."observed_at" + interval '10 seconds')));